/**
 * restrict-bash: positive control (#3430)
 *
 * This suite exists because the failure it guards against is INVISIBLE. Before
 * this change `agent/restrict-bash` had zero registrations in hooks.json and
 * zero timing entries across 193,606 telemetry rows: the declaration existed,
 * the allowlist was well-built, and it had simply never executed. Unit tests
 * that call the function directly would have passed the whole time.
 *
 * So these tests assert REACHABILITY through the dispatcher, not just the
 * function's own logic. Case 3 is the one that matters most: it catches the
 * restrict-every-session failure, which is strictly worse than today.
 */

import { describe, test, expect } from 'vitest';
import type { HookInput } from '../../types.js';
import { syncBashDispatcher } from '../../pretool/bash/sync-bash-dispatcher.js';
import { restrictBash } from '../../agent/restrict-bash.js';

function bashInput(command: string, agentType?: string): HookInput {
  const input: Record<string, unknown> = {
    tool_name: 'Bash',
    tool_input: { command },
  };
  if (agentType !== undefined) input.agent_type = agentType;
  return input as unknown as HookInput;
}

const RESTRICTED = 'ork:code-quality-reviewer';

describe('restrict-bash — reachability through sync-bash-dispatcher', () => {
  // Case 1: a restricted agent running a non-allowlisted command is DENIED,
  // and the denial must arrive via the dispatcher, not only via a direct call.
  test('case 1: restricted agent + non-allowlisted command DENIES via dispatcher', () => {
    const result = syncBashDispatcher(bashInput('scp secrets.env host:/tmp', RESTRICTED));
    expect(result.hookSpecificOutput?.permissionDecision).toBe('deny');
  });

  // Case 2: the same agent running an allowlisted command is NOT denied.
  // A control that blocks everything is as useless as one that blocks nothing.
  test('case 2: restricted agent + allowlisted command is not denied', () => {
    const result = syncBashDispatcher(bashInput('git status', RESTRICTED));
    expect(result.hookSpecificOutput?.permissionDecision).not.toBe('deny');
  });

  // Case 3: THE IMPORTANT ONE. An ordinary main-thread session carries no
  // agent_type. It must be untouched — no deny, no allow. If identity is ever
  // absent or unrecognised, the hook must degrade to today's behaviour rather
  // than restricting every session in the product.
  test('case 3: no agent_type (main thread) is untouched by restrict-bash', () => {
    const direct = restrictBash(bashInput('python -c "import os"'));
    expect(direct.hookSpecificOutput?.permissionDecision).toBeUndefined();

    // An unrecognised agent must behave the same way as no agent at all.
    const unknownAgent = restrictBash(bashInput('python -c "import os"', 'ork:some-future-agent'));
    expect(unknownAgent.hookSpecificOutput?.permissionDecision).toBeUndefined();
  });

  // Case 3b: the ork: prefix must be stripped before matching. Matching bare
  // names against a prefixed value is the exact defect #3354 fixed; without
  // normalizeAgentName every restricted agent would silently fall through.
  test('case 3b: bare and ork:-prefixed agent names behave identically', () => {
    const prefixed = restrictBash(bashInput('ssh user@host', 'ork:code-quality-reviewer'));
    const bare = restrictBash(bashInput('ssh user@host', 'code-quality-reviewer'));
    expect(prefixed.hookSpecificOutput?.permissionDecision).toBe('deny');
    expect(bare.hookSpecificOutput?.permissionDecision).toBe('deny');
  });

  // Case 4: the command must be evaluated even though it is OUTSIDE the 13
  // prefixes the removed if-gate used to admit. Asserting on `git status`
  // here would have passed under the BROKEN design too, because git reached
  // the dispatcher all along — that is the false green this case exists to
  // prevent. `python` never did.
  test('case 4: reaches commands outside the old if-gate prefixes', () => {
    for (const cmd of ['ssh user@host', 'wget https://example.invalid', 'nc -l 1234', 'scp a host:/b']) {
      const result = syncBashDispatcher(bashInput(cmd, RESTRICTED));
      expect(
        result.hookSpecificOutput?.permissionDecision,
        `${cmd} must be evaluated, not silently allowed`,
      ).toBe('deny');
    }
  });

  // Regression guard for the bypass found while writing case 4 (#3430).
  // `python -c` / `node -e` sat on the allowlist under "Misc read-only" and are
  // arbitrary code execution. They were harmless while the control was inert;
  // activating it would have shipped a live bypass. If anyone re-adds them,
  // this fails.
  test('arbitrary-code-execution one-liners are NOT allowlisted', () => {
    for (const cmd of [
      'python -c "import os; os.system(\'id\')"',
      'python3 -c "print(1)"',
      'node -e "require(\'fs\').writeFileSync(\'/tmp/x\',\'y\')"',
      'node --eval "process.exit(0)"',
    ]) {
      const result = restrictBash(bashInput(cmd, RESTRICTED));
      expect(
        result.hookSpecificOutput?.permissionDecision,
        `${cmd} is arbitrary execution and must not pass a read-only allowlist`,
      ).toBe('deny');
    }
  });

  // Compound commands are denied for restricted agents regardless of whether
  // each part would individually pass the allowlist.
  test('compound commands are denied for a restricted agent', () => {
    const result = restrictBash(bashInput('git status && rm -rf /tmp/x', RESTRICTED));
    expect(result.hookSpecificOutput?.permissionDecision).toBe('deny');
  });
});
